16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email;
99	    }
100	
101	    public LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    public String getCustomerCode() {
110	        return this.customerCode;
111	    }
112	
113	    public void setCustomerCode(String customerCode) {
114	        this.customerCode = customerCode;
115	    }
116	
117	    /**
118	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
119	     * {@code YY} is the last two digits of the {@code registrationDate} year, e.g.
120	     * {@code "SYD-SMI-0007-M26"}. Derived from the owner's own fields; {@code null} until
121	     * both the customer code and registration date have been assigned.
122	     */
123	    @Transient
124	    public String getMembershipNumber() {
125	        if (this.customerCode == null || this.registrationDate == null) {
126	            return null;
127	        }
128	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
129	    }
130	
131	    /**
132	     * The owner's membership tier, derived on read from the owner's own fields:
133	     * {@link MembershipTier#SILVER} when the owner has no namesakes
134	     * ({@code namesakeCount} is 0) and an email address is present, otherwise
135	     * {@link MembershipTier#BRONZE}.
136	     */
137	    @Transient
138	    public MembershipTier getMembershipTier() {
139	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
140	        boolean hasEmail = this.email != null && !this.email.isBlank();
141	        return noNamesakes && hasEmail ? MembershipTier.SILVER : MembershipTier.BRONZE;
142	    }
143	
144	    /**
145	     * The owner's locality: the canonical region derived on read from the owner's
146	     * {@link #city} via the fixed {@link CityRegionTable}, or {@code "UNKNOWN"} when
147	     * the city has no known region.
148	     */
149	    @Transient
150	    public String getLocality() {
151	        return CityRegionTable.regionOf(this.city);
152	    }
153	
154	    public String getHouseholdId() {
155	        return this.householdId;
156	    }
157	
158	    public void setHouseholdId(String householdId) {
159	        this.householdId = householdId;
160	    }
161	
162	    public Integer getNamesakeCount() {
163	        return this.namesakeCount;
164	    }
165	
166	    public void setNamesakeCount(Integer namesakeCount) {
167	        this.namesakeCount = namesakeCount;
168	    }
169	
170	    protected Set<Pet> getPetsInternal() {
171	        if (this.pets == null) {
172	            this.pets = new HashSet<>();
173	        }
174	        return this.pets;
175	    }
176	
177	    protected void setPetsInternal(Set<Pet> pets) {
178	        this.pets = pets;
179	    }
180	
181	    public List<Pet> getPets() {
182	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
183	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
184	        return Collections.unmodifiableList(sortedPets);
185	    }
186	
187	    public void setPets(List<Pet> pets) {
188	        this.pets = new HashSet<>(pets);
189	    }
190	
191	    public void addPet(Pet pet) {
192	        getPetsInternal().add(pet);
193	        pet.setOwner(this);
194	    }
195	
196	    /**
197	     * Return the Pet with the given name, or null if none found for this Owner.
198	     *
199	     * @param name to test
200	     * @return true if pet name is already in use
201	     */
202	    public Pet getPet(String name) {
203	        return getPet(name, false);
204	    }
205	
206	    /**
207	     * Return the Pet with the given name, or null if none found for this Owner.
208	     *
209	     * @param name to test
210	     * @return true if pet name is already in use
211	     */
212	    public Pet getPet(String name, boolean ignoreNew) {
213	        name = name.toLowerCase();
214	        for (Pet pet : getPetsInternal()) {
215	            if (!ignoreNew || !pet.isNew()) {
216	                String compName = pet.getName();
217	                compName = compName.toLowerCase();
218	                if (compName.equals(name)) {
219	                    return pet;
220	                }
221	            }
222	        }
223	        return null;
224	    }
225	
226	    public Pet getPet(Integer petId) {
227	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
228	    }
229	
230	    @Override
231	    public String toString() {
232	        return new ToStringCreator(this)
233	
234	            .append("id", this.getId())
235	            .append("new", this.isNew())
236	            .append("lastName", this.getLastName())
237	            .append("firstName", this.getFirstName())
238	            .append("address", this.address)
239	            .append("city", this.city)
240	            .append("telephone", this.telephone)
241	            .append("email", this.email)
242	            .append("registrationDate", this.registrationDate)
243	            .append("customerCode", this.customerCode)
244	            .toString();
245	    }
246	}
