17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.controller.CustomerCodeAssigner;
33	import org.springframework.samples.petclinic.rest.controller.HouseholdAssigner;
34	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateChecker;
35	import org.springframework.samples.petclinic.rest.controller.NamesakeCounter;
36	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
37	import org.springframework.samples.petclinic.rest.controller.RegistrationDateDefaulter;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.WebDataBinder;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.InitBinder;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    private final OwnerFieldsValidator ownerFieldsValidator;
73	
74	    private final RegistrationDateDefaulter registrationDateDefaulter;
75	
76	    private final CustomerCodeAssigner customerCodeAssigner;
77	
78	    private final HouseholdDuplicateChecker householdDuplicateChecker;
79	
80	    private final HouseholdAssigner householdAssigner;
81	
82	    private final NamesakeCounter namesakeCounter;
83	
84	    public OwnerRestControllerV1(ClinicService clinicService,
85	                                 OwnerMapper ownerMapper,
86	                                 PetMapper petMapper,
87	                                 VisitMapper visitMapper,
88	                                 OwnerFieldsValidator ownerFieldsValidator,
89	                                 RegistrationDateDefaulter registrationDateDefaulter,
90	                                 CustomerCodeAssigner customerCodeAssigner,
91	                                 HouseholdDuplicateChecker householdDuplicateChecker,
92	                                 HouseholdAssigner householdAssigner,
93	                                 NamesakeCounter namesakeCounter) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	        this.ownerFieldsValidator = ownerFieldsValidator;
99	        this.registrationDateDefaulter = registrationDateDefaulter;
100	        this.customerCodeAssigner = customerCodeAssigner;
101	        this.householdDuplicateChecker = householdDuplicateChecker;
102	        this.householdAssigner = householdAssigner;
103	        this.namesakeCounter = namesakeCounter;
104	    }
105	
106	    @InitBinder("ownerFieldsDto")
107	    void initOwnerFieldsBinder(WebDataBinder binder) {
108	        binder.addValidators(ownerFieldsValidator);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        if (this.clinicService.ownerExistsWithTelephone(owner.getTelephone())) {
142	            return new ResponseEntity<>(HttpStatus.CONFLICT);
143	        }
144	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
145	        boolean duplicate = this.householdDuplicateChecker.isDuplicate(owner);
146	        if (duplicate && !sharesHousehold) {
147	            return new ResponseEntity<>(HttpStatus.CONFLICT);
148	        }
149	        if (duplicate) {
150	            this.householdAssigner.assign(owner);
151	        }
152	        this.registrationDateDefaulter.applyDefault(owner);
153	        this.customerCodeAssigner.assign(owner);
154	        this.namesakeCounter.assign(owner);
155	        this.clinicService.saveOwner(owner);
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        currentOwner.setAddress(ownerFieldsDto.getAddress());
170	        currentOwner.setCity(ownerFieldsDto.getCity());
171	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
172	        currentOwner.setLastName(ownerFieldsDto.getLastName());
173	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
174	        currentOwner.setEmail(ownerFieldsDto.getEmail());
175	        this.clinicService.saveOwner(currentOwner);
176	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Transactional
181	    @Override
182	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        this.clinicService.deleteOwner(owner);
188	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        HttpHeaders headers = new HttpHeaders();
199	        Pet pet = petMapper.toPet(petFieldsDto);
200	        owner.setId(ownerId);
201	        pet.setOwner(owner);
202	        pet.getType().setName(null);
203	        this.clinicService.savePet(pet);
204	        PetDto petDto = petMapper.toPetDto(pet);
205	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
206	            .buildAndExpand(pet.getId()).toUri());
207	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
213	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
214	        if (currentOwner != null) {
215	            Pet currentPet = this.clinicService.findPetById(petId);
216	            if (currentPet != null) {
217	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
218	                currentPet.setName(petFieldsDto.getName());
219	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
220	                this.clinicService.savePet(currentPet);
221	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
222	            }
223	        }
224	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
230	        HttpHeaders headers = new HttpHeaders();
231	        Visit visit = visitMapper.toVisit(visitFieldsDto);
232	        Pet pet = new Pet();
233	        pet.setId(petId);
234	        visit.setPet(pet);
235	        this.clinicService.saveVisit(visit);
236	        VisitDto visitDto = visitMapper.toVisitDto(visit);
237	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
238	            .buildAndExpand(visit.getId()).toUri());
239	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
240	    }
241	
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner != null) {
248	            Pet pet = owner.getPet(petId);
249	            if (pet != null) {
250	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	}
