23	/**
24	 * Records, on create, how many already-stored owners share the new owner's name.
25	 * <p>
26	 * Two owners are namesakes when their first name and last name are equal ignoring case.
27	 * The count reflects the owners stored before this create, so it must be assigned before
28	 * the owner is saved.
29	 */
30	@Component
31	public class NamesakeCounter {
32	
33	    private final ClinicService clinicService;
34	
35	    public NamesakeCounter(ClinicService clinicService) {
36	        this.clinicService = clinicService;
37	    }
38	
39	    /**
40	     * Assigns {@code owner}'s namesake count: the number of already-stored owners sharing
41	     * its first name and last name, compared case-insensitively. Call this before the
42	     * owner is saved so it does not count itself.
43	     *
44	     * @param owner the owner being created
45	     */
46	    public void assign(Owner owner) {
47	        long count = clinicService.findAllOwners().stream()
48	            .filter(existing -> isNamesake(existing, owner))
49	            .count();
50	        owner.setNamesakeCount(Math.toIntExact(count));
51	    }
52	
53	    private boolean isNamesake(Owner existing, Owner candidate) {
54	        return equalsIgnoreCase(existing.getFirstName(), candidate.getFirstName())
55	            && equalsIgnoreCase(existing.getLastName(), candidate.getLastName());
56	    }
57	
58	    private boolean equalsIgnoreCase(String a, String b) {
59	        return a == null ? b == null : a.equalsIgnoreCase(b);
60	    }
61	}
